      "test": "/**
 * @jest-environment jsdom
 */
import * as React from 'react';
import { render, screen, within, cleanup } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';

// Import Footer (handles both default and named export)
const FooterModule = require('../src/components/Footer');
const Footer = FooterModule.Footer || FooterModule.default;

afterEach(cleanup);

describe('Footer extra column removal', () => {
  test('REPRO: Footer: remove the extra, unlabeled column of links (Services, Systems, Training, Engagements, About, Contact) at the right of the footer, on desktop and phones.', () => {
    render(
      <MemoryRouter>
        <Footer />
      </MemoryRouter>,
    );

    const footer = screen.getByRole('contentinfo'); // <footer> has role 'contentinfo'
    const allLinks = within(footer).getAllByRole('link');

    // Find the mailto link
    const emailLinks = allLinks.filter((link) => {
      const href = link.getAttribute('href') ?? '';
      return href.startsWith('mailto:');
    });
    expect(emailLinks).toHaveLength(1);
    const emailLink = emailLinks[0];
    expect(emailLink).toHaveAttribute('href');
    expect(emailLink.textContent?.trim()).toMatch(/hello@thebayesgroup\.com/i);

    // Non‑email links (services + company)
    const nonEmailLinks = allLinks.filter((link) => {
      const href = link.getAttribute('href') ?? '';
      return !href.startsWith('mailto:');
    });

    const expectedLinkTexts = [
      'AI Enablement',
      'Training',
      'Custom Development',
      'Systems engineering',
      'Engagements',
      'About',
      'Contact',
    ];
    expect(nonEmailLinks).toHaveLength(expectedLinkTexts.length);
    const actualTexts = nonEmailLinks.map((l) => l.textContent?.trim() ?? '');
    expectedLinkTexts.forEach((txt) => {
      expect(actualTexts).toContain(txt);
    });

    // Ensure no extra top‑level navigation links appear in the footer
    const extraNames = ['Services', 'Systems', 'Training', 'Engagements'];
    extraNames.forEach((name) => {
      expect(actualTexts).not.toContain(name);
    });
  });
});"
